CREATE DATABASE IF NOT EXISTS studio_portal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE studio_portal;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS audit_logs,notifications,project_assignments,projects,payroll_records,salary_history,salaries,employee_skills,software,skills,attendance,users,employees,job_titles,departments,settings;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE settings(setting_key VARCHAR(80) PRIMARY KEY,setting_value TEXT NOT NULL);
INSERT INTO settings VALUES ('studio_name','FrameForge Studio'),('timezone','Asia/Karachi'),('currency','PKR'),('work_start','09:00:00'),('work_end','18:00:00'),('grace_minutes','15');
CREATE TABLE departments(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO departments(name) VALUES ('Motion Design'),('2D Animation'),('3D'),('VFX'),('Compositing'),('Video Editing'),('Color Grading'),('Sound'),('Creative'),('Production'),('Post Production'),('Technical / Pipeline'),('Management'),('Administration');
CREATE TABLE job_titles(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120) NOT NULL UNIQUE,active TINYINT(1) DEFAULT 1);
INSERT INTO job_titles(title) VALUES ('Creative Director'),('Senior Motion Designer'),('Motion Designer'),('2D Animator'),('3D Artist'),('VFX Artist'),('Compositor'),('Video Editor'),('Colorist'),('Sound Designer'),('Creative Producer'),('Production Manager'),('Pipeline TD'),('HR Manager'),('Finance Manager'),('Administrator');
CREATE TABLE employees(id INT AUTO_INCREMENT PRIMARY KEY,employee_code VARCHAR(30) NOT NULL UNIQUE,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,phone VARCHAR(30),address TEXT,date_of_birth DATE NULL,gender VARCHAR(20),department_id INT NULL,job_title_id INT NULL,manager_id INT NULL,joining_date DATE NULL,employment_type ENUM('Full Time','Part Time','Contract','Freelance','Intern') DEFAULT 'Full Time',employment_status ENUM('Active','Inactive','On Leave','Resigned') DEFAULT 'Active',specialty VARCHAR(100),profile_photo VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(id),FOREIGN KEY(job_title_id) REFERENCES job_titles(id),FOREIGN KEY(manager_id) REFERENCES employees(id));
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL UNIQUE,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','employee') DEFAULT 'employee',remember_token VARCHAR(64),active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE software(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,active TINYINT(1) DEFAULT 1);
INSERT INTO software(name) VALUES ('Adobe After Effects'),('Premiere Pro'),('Photoshop'),('Illustrator'),('Blender'),('Cinema 4D'),('Maya'),('Houdini'),('Nuke'),('DaVinci Resolve'),('Unreal Engine'),('Substance 3D'),('Redshift'),('Octane'),('Arnold');
CREATE TABLE employee_skills(id INT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,software_id INT NULL,custom_skill VARCHAR(100),skill_level ENUM('Beginner','Intermediate','Advanced','Expert') DEFAULT 'Intermediate',FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE,FOREIGN KEY(software_id) REFERENCES software(id) ON DELETE CASCADE);
CREATE TABLE attendance(id INT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,work_date DATE NOT NULL,check_in DATETIME NULL,check_out DATETIME NULL,total_seconds INT DEFAULT 0,status ENUM('Present','Late','Absent','Half Day','Leave','Holiday','Weekend','Incomplete') DEFAULT 'Incomplete',late_minutes INT DEFAULT 0,overtime_minutes INT DEFAULT 0,notes TEXT,UNIQUE KEY employee_day(employee_id,work_date),FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE salaries(id INT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL UNIQUE,base_salary DECIMAL(12,2) DEFAULT 0,allowances DECIMAL(12,2) DEFAULT 0,bonuses DECIMAL(12,2) DEFAULT 0,deductions DECIMAL(12,2) DEFAULT 0,overtime_rate DECIMAL(12,2) DEFAULT 0,effective_date DATE NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE salary_history(id INT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,old_base DECIMAL(12,2) DEFAULT 0,new_base DECIMAL(12,2) DEFAULT 0,reason TEXT,changed_by INT NULL,changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE,FOREIGN KEY(changed_by) REFERENCES employees(id));
CREATE TABLE payroll_records(id INT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,payroll_month CHAR(7) NOT NULL,base_salary DECIMAL(12,2),allowances DECIMAL(12,2),bonuses DECIMAL(12,2),deductions DECIMAL(12,2),net_salary DECIMAL(12,2),payment_status ENUM('Pending','Paid') DEFAULT 'Pending',paid_at DATETIME NULL,UNIQUE KEY payroll_employee_month(employee_id,payroll_month),FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE projects(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,client VARCHAR(160),project_type VARCHAR(100),status ENUM('Planned','Pre-Production','In Production','Review','Revisions','Completed','Archived') DEFAULT 'Planned',start_date DATE NULL,deadline DATE NULL,description TEXT,attachment_path VARCHAR(255),created_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES employees(id));
CREATE TABLE project_assignments(id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,employee_id INT NOT NULL,assignment_role VARCHAR(100),assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY project_employee(project_id,employee_id),FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,title VARCHAR(160) NOT NULL,message TEXT NOT NULL,type ENUM('announcement','info','alert') DEFAULT 'info',is_read TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE audit_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(160) NOT NULL,entity VARCHAR(80),entity_id INT NULL,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES employees(id) ON DELETE SET NULL);
